import { ComponentProps } from "react";
import { ShopServicePaymentCartWrapper } from "./shop-service-payment-cart-wrapper";
import { Meta, StoryObj } from "@storybook/react";
import { useArgs } from "storybook/preview-api";
import { GiftCardPaymentResponseItem } from "@parksandresorts/webapiproxy-types";
import {
  mockCheckoutService,
  mockProducts,
} from "@/core/components/modules/shop-service-payment/shop-service-payment-shared-storybook";
import { PageProviders } from "../../../providers";
import { LocalStorageHelper, PlaceholderImageHelper } from "../../../helpers";

const meta = {
  title: "Modules/ShopService Payment Cart Wrapper",
  component: ShopServicePaymentCartWrapper,
} satisfies Meta<typeof ShopServicePaymentCartWrapper>;

export default meta;

type StoryProps = ComponentProps<typeof ShopServicePaymentCartWrapper> & {
  giftCards: Array<GiftCardPaymentResponseItem>;
  withGiftCardInCart: boolean;
};

type Story = StoryObj<StoryProps>;

export const Primary: Story = {
  args: {
    enabled: true,
    shopUrlSlugOverrides: undefined,
    giftCards: [],
    withGiftCardInCart: false,
  },
  render: function RenderComponent(_args) {
    LocalStorageHelper.getItem = () => "test-cart-id"; // Set a test cart ID in local storage
    const [{ giftCards, withGiftCardInCart, ...args }, setArgs] = useArgs<typeof _args>();
    // Mocking the CheckoutService methods to return the predefined responses
    mockCheckoutService(giftCards, withGiftCardInCart, setArgs);
    PlaceholderImageHelper.getPlaceholderImage = () => "/mock-data/grona-lund-logo.svg";
    return (
      <PageProviders
        currentContentPageData={{ currentLocale: "sv" } as any}
        staticConfigData={{
          eCommerce: {
            preferredPaymentProvider: "Klarna",
            shopServiceCheckoutSlug: "/checkout",
            shopServiceConfirmationSlug: "/confirm",
            shopServicePaymentSlug: "/payment",
          },
          products: mockProducts,
        }}
      >
        <ShopServicePaymentCartWrapper {...args} />
      </PageProviders>
    );
  },
};

export const WithGiftCards: Story = {
  ...Primary,
  args: {
    ...Primary.args,
    giftCards: [
      {
        cardIdentifier: "12345678",
        expiresOn: "2024-12-31T23:59:59Z",
        balanceBeforePayment: 1000,
        reservedAmount: 500,
        balanceAfterPayment: 500,
      },
    ],
  },
};
