import { useMemo } from "react";
import { useTranslation } from "react-i18next";
import type { ItemInCart } from "@/core/components/modules/cart/cart-item";
import { DeliveryType, WebshopProductType } from "@parksandresorts/webapiproxy-types";
import { isNonEmptyArray, isShippingFeeProduct } from "../helpers";
import { GlkBackedProduct } from "./product-hooks";

export function useDeliveryItemsFromCart(
  cartItems: Array<ItemInCart>,
  productsById: ReadonlyMap<number, GlkBackedProduct>,
): ItemInCart[] {
  const { t } = useTranslation();
  return useMemo(() => {
    if (!isNonEmptyArray(cartItems)) return [];

    const hasDigitalProducts = cartItems.some((i) => i.deliveryType === DeliveryType.DIGITAL);
    const hasHomeProducts = cartItems.some((i) => i.deliveryType === DeliveryType.HOME);

    const homeDeliveryCost = cartItems
      .filter((i) => isShippingFeeProduct(productsById.get(i.productId ?? 0)))
      .reduce((sum, i) => sum + (i.unitPriceIncludingVat ?? i.price ?? 0), 0);

    const rows: Array<ItemInCart> = [];

    if (hasDigitalProducts) {
      rows.push({
        productId: null,
        id: "delivery-digital",
        name: t("digitalDelivery"),
        price: 0,
        unitPriceIncludingVat: 0,
        quantity: 1,
        minimumQuantity: 1,
        visitorName: undefined,
        subItems: [],
        metadata: [t("digitalDeliveryDescription")],
        deliveryType: DeliveryType.DIGITAL,
        data: undefined,
        productType: WebshopProductType.SHIPPING_FEE,
      });
    }

    if (hasHomeProducts) {
      rows.push({
        productId: null,
        id: "delivery-home",
        name: t("homeDelivery"),
        price: homeDeliveryCost,
        unitPriceIncludingVat: homeDeliveryCost,
        quantity: 1,
        minimumQuantity: 1,
        visitorName: undefined,
        subItems: [],
        deliveryType: DeliveryType.HOME,
        data: undefined,
        productType: WebshopProductType.SHIPPING_FEE,
      });
    }

    return rows;
  }, [cartItems, productsById, t]);
}
