import { useShopServiceCartContext } from "@/core/contexts";
import {
  ShopServicePayment,
  ShopServicePaymentProps,
} from "@/core/components/modules/shop-service-payment/shop-service-payment";
import {
  isNonEmptyArray,
  CurrencyHelper,
  usedVoucherCodesSummaryItems,
  ECommerceHelper,
  multipleClassNames,
  getProductIds,
  isShippingFeeProduct,
} from "@/core/helpers";
import SummaryList from "@/core/components/primitives/summary-list/summary-list";
import { SummaryTotal } from "@/core/components/primitives/summary-total/summary-total";
import { ContinueShoppingButton } from "@/core/components/modules/cart/cart";
import { useTranslation } from "react-i18next";
import { ShopServiceCart } from "@/core/components/modules/cart/shop-service-cart";
import Cart from "@/core/components/modules/cart/cart";
import { useCartItemsFromCartResponse, useRemoveVoucherFromCart } from "@/core/hooks";
import { useMemo } from "react";
import { useDeliveryItemsFromCart } from "@/core/hooks/use-delivery-items-from-cart";
import styles from "./shop-service-payment-cart-wrapper.module.less";
import { useProducts } from "@/core/hooks/product-hooks";
import { UsedVoucherCode } from "@/core/components/primitives/used-voucher-code/used-voucher-code";

export type ShopServiceCartWrapperProps = Omit<ShopServicePaymentProps, "cartId">;
export const ShopServicePaymentCartWrapper = (props: ShopServiceCartWrapperProps) => {
  const continueShoppingLabel = ECommerceHelper.jetshop?.continueShoppingLabel;
  const continueShoppingLink = ECommerceHelper.jetshop?.continueShoppingLink;
  const { data: cart, cartId } = useShopServiceCartContext();
  const { t } = useTranslation();

  const cartItems = useCartItemsFromCartResponse(cart?.cartItems, cart);

  const { productsById } = useProducts(getProductIds(cartItems));

  const numItemsWithoutShipping = useMemo(() => {
    if (!cartItems) {
      return 0;
    }
    return cartItems
      .filter((p) => !isShippingFeeProduct(productsById.get(p.productId ?? 0)))
      .reduce((acc, { quantity }) => acc + quantity, 0);
  }, [cartItems, productsById]);

  const totalSum = cart?.cartPrice.amount?.amountIncludingVat ?? 0;

  const usedVouchers = usedVoucherCodesSummaryItems(cart?.voucherCodes ?? [], cart?.redeemableValidationResults ?? []);

  const { mutate: removeVoucherCode, isPending: removeVoucherCodePending } = useRemoveVoucherFromCart(
    cart?.cartGuid ?? "",
  );

  const displayCartAndPayment = useMemo(() => cart && isNonEmptyArray(cart.cartItems), [cart]);

  const deliveryRows = useDeliveryItemsFromCart(cartItems ?? [], productsById);

  return (
    <div className={styles.wrapper} data-has-cart={!!displayCartAndPayment}>
      {displayCartAndPayment && (
        <SummaryList
          category={t("paymentSummary")}
          quantity={t("summaryStepPieces", { count: numItemsWithoutShipping })}
          sumPrice={CurrencyHelper.formatToSek(totalSum)}
          preExpanded
          removeChildrenWhenUnexpanded
          ariaLabelsIcon={{
            whenExpanded: t("paymentSummaryIconExpanded"),
            whenCollapsed: t("paymentSummaryIconCollapsed"),
          }}
        >
          <ShopServiceCart
            hideHeadline
            hideContinueShopping
            hideGoToCheckout
            hideTotalSum
            innerWrapperClassName={styles.cartInnerWrapper}
            hideShippingProducts
          />
        </SummaryList>
      )}

      {displayCartAndPayment && isNonEmptyArray(deliveryRows) && (
        <SummaryList
          preExpanded
          category={t("delivery")}
          quantity=""
          removeChildrenWhenUnexpanded
          ariaLabelsIcon={{
            whenExpanded: t("deliveryIconExpanded"),
            whenCollapsed: t("deliveryIconCollapsed"),
          }}
        >
          <Cart
            hideHeadline
            hideContinueShopping
            hideGoToCheckout
            hideTotalSum
            checkoutUrl={undefined}
            isDisabled
            totalSumInclVat={0}
            products={deliveryRows}
            deleteCartItem={() => undefined}
            updateCartItemQuantity={() => undefined}
            innerWrapperClassName={multipleClassNames(styles.cartInnerWrapper, styles.deliveryCartInnerWrapper)}
          />
        </SummaryList>
      )}
      {isNonEmptyArray(usedVouchers) && (
        <SummaryList
          preExpanded
          category={t("usedVoucherCodes")}
          quantity={t("summaryStepPieces", { count: usedVouchers.length })}
          ariaLabelsIcon={{
            whenExpanded: t("usedVoucherCodesIconExpanded"),
            whenCollapsed: t("usedVoucherCodesIconCollapsed"),
          }}
        >
          {usedVouchers.map((voucher, index) => (
            <UsedVoucherCode
              key={index}
              code={voucher.code}
              variant={voucher.variant}
              disabled={removeVoucherCodePending}
              onDelete={() => {
                removeVoucherCode(voucher.code);
              }}
              description={voucher.description}
            />
          ))}
        </SummaryList>
      )}
      {displayCartAndPayment && (
        <SummaryTotal
          type="price"
          labelId="cartSummary"
          price={totalSum}
          originalProductSummaryAmount={cart?.cartPrice.amountBeforeDiscounts?.amountIncludingVat}
        />
      )}
      <ShopServicePayment {...props} cartId={cartId} />
      {!displayCartAndPayment && (
        <div className={styles.emptyCartMessage}>
          <p className="">{t("emptyCart")}</p>
          <ContinueShoppingButton
            continueShoppingLabel={continueShoppingLabel}
            continueShoppingLink={continueShoppingLink}
            variant="primary"
          />
        </div>
      )}
    </div>
  );
};
